private val searchStopWords = setOf(
    "about", "after", "again", "cannot", "could", "from", "have", "into", "with",
    "what", "when", "where", "which", "would", "should", "that", "this", "they",
    "them", "then", "your", "feel", "feeling"
)

/** Local, deterministic intent search designed for everyday phrases rather than exact FAQ wording. */
fun searchAskKrishnaQuestions(query: String): List<AskKrishnaQuestion> {
    val normalized = query.lowercase().replace(Regex("[^a-z0-9 ]"), " ").replace(Regex("\\s+"), " ").trim()
    if (normalized.isEmpty()) return askKrishnaQuestions
    val queryTokens = normalized.split(" ").filter { it.length > 2 && it !in searchStopWords }

    return askKrishnaQuestions.mapNotNull { entry ->
        val aliases = realLifeSearchAliases[entry.id].orEmpty()
        val searchable = (listOf(entry.question, entry.answer) + aliases).joinToString(" ").lowercase()
        val exactIntent = aliases.any { alias -> normalized.contains(alias) || alias.contains(normalized) }
        val tokenHits = queryTokens.count { it in searchable }
        val score = (if (exactIntent) 100 else 0) + tokenHits
        if (score > 0) entry to score else null
    }.sortedWith(compareByDescending<Pair<AskKrishnaQuestion, Int>> { it.second }.thenBy { it.first.id })
        .map { it.first }
}
